<div class="modal fade" id="documentPreviewModal" tabindex="-1" aria-labelledby="documentPreviewTitle" aria-hidden="true"><div class="modal-dialog modal-xl modal-dialog-centered"><div class="modal-content"><div class="modal-header"><h2 class="modal-title fs-5 text-start" id="documentPreviewTitle">Document preview</h2><button class="btn-close ms-auto" type="button" data-bs-dismiss="modal" aria-label="Close"></button></div><div class="modal-body p-0"><iframe id="documentPreviewFrame" title="Document preview" style="width:100%;height:75vh;border:0"></iframe></div><div class="modal-footer justify-content-end"><a class="btn btn-outline-brand" id="documentPreviewDownload" href="#">Download</a></div></div></div></div>
<script>document.addEventListener('DOMContentLoaded',()=>{const element=document.getElementById('documentPreviewModal'),frame=document.getElementById('documentPreviewFrame'),title=document.getElementById('documentPreviewTitle'),download=document.getElementById('documentPreviewDownload'),modal=new bootstrap.Modal(element);document.addEventListener('click',event=>{const button=event.target.closest('[data-document-preview]');if(!button)return;event.preventDefault();title.textContent=button.dataset.documentName;frame.src=button.dataset.documentPreview;download.href=button.dataset.documentPreview.replace(/\/preview$/,'');modal.show()});element.addEventListener('hidden.bs.modal',()=>frame.src='about:blank')})</script>
